.ul-morph {
  --c1: #0071e3;
  --c2: #8ec5ff;
  --s: 72px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --bg: #f5f5f7;
}

.ul-morph {
  width: var(--s);
  height: var(--s);
  background: var(--c1);
  animation: ul-morph calc(2s / var(--k)) cubic-bezier(.65,0,.35,1) infinite;
}

@keyframes ul-morph {
  0% {
    transform: rotate(0) scale(1);
    border-radius: 18%;
  }
  50% {
    transform: rotate(180deg) scale(.8);
    border-radius: 50%;
    background: var(--c2);
  }
  100% {
    transform: rotate(360deg) scale(1);
    border-radius: 18%;
  }
}

