.ul-grid {
  --c1: #0071e3;
  --c2: #8ec5ff;
  --s: 72px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --bg: #f5f5f7;
}

.ul-grid {
  position: relative;
  width: var(--s);
  height: var(--s);
}

.ul-grid i {
  position: absolute;
  width: 44%;
  height: 44%;
  border-radius: 24%;
  background: var(--c1);
  animation: ul-grid calc(2.4s / var(--k)) cubic-bezier(.65,0,.35,1) infinite;
  animation-delay: calc(var(--i) * -0.6s / var(--k));
}

.ul-grid i:nth-child(2) {
  background: var(--c2);
}

@keyframes ul-grid {
  0%,18% {
    transform: translate(0,0);
  }
  25%,43% {
    transform: translate(127%,0);
  }
  50%,68% {
    transform: translate(127%,127%);
  }
  75%,93% {
    transform: translate(0,127%);
  }
  100% {
    transform: translate(0,0);
  }
}

