css:
.ul-cube-w {
  --c1: #0071e3;
  --c2: #8ec5ff;
  --s: 72px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --bg: #f5f5f7;
}

.ul-cube-w {
  perspective: calc(var(--s) * 8);
}

.ul-cube {
  position: relative;
  width: var(--s);
  height: var(--s);
  transform-style: preserve-3d;
  animation: ul-cube calc(3s / var(--k)) cubic-bezier(.65,0,.35,1) infinite;
}

.ul-cube i {
  position: absolute;
  inset: 0;
  border-radius: 8%;
  background: var(--c1);
}

.ul-cube i:nth-child(1) {
  transform: translateZ(calc(var(--s) / 2));
}

.ul-cube i:nth-child(2) {
  transform: rotateY(180deg) translateZ(calc(var(--s) / 2));
}

.ul-cube i:nth-child(3) {
  transform: rotateY(90deg) translateZ(calc(var(--s) / 2));
  background: color-mix(in srgb,var(--c1) 70%,#000);
}

.ul-cube i:nth-child(4) {
  transform: rotateY(-90deg) translateZ(calc(var(--s) / 2));
  background: color-mix(in srgb,var(--c1) 70%,#000);
}

.ul-cube i:nth-child(5) {
  transform: rotateX(90deg) translateZ(calc(var(--s) / 2));
  background: var(--c2);
}

.ul-cube i:nth-child(6) {
  transform: rotateX(-90deg) translateZ(calc(var(--s) / 2));
  background: var(--c2);
}

@keyframes ul-cube {
  0% {
    transform: rotateX(-30deg) rotateY(45deg);
  }
  50% {
    transform: rotateX(-30deg) rotateY(225deg);
  }
  100% {
    transform: rotateX(-30deg) rotateY(405deg);
  }
}

