css:
.ul-hex {
  --c1: #0071e3;
  --c2: #8ec5ff;
  --s: 72px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --bg: #f5f5f7;
}

.ul-hex {
  position: relative;
  width: calc(var(--s) * 1.4);
  height: calc(var(--s) * 1.4);
}

.ul-hex i {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 32%;
  height: 28%;
  margin: -14% 0 0 -16%;
  clip-path: polygon(25% 0,75% 0,100% 50%,75% 100%,25% 100%,0 50%);
  background: var(--c1);
  opacity: .15;
  transform: rotate(calc(var(--i) * 60deg)) translateY(-118%) rotate(calc(var(--i) * -60deg));
  animation: ul-hex calc(1.8s / var(--k)) ease-in-out infinite;
  animation-delay: calc(var(--i) * 0.3s / var(--k));
}

@keyframes ul-hex {
  0%,100% {
    opacity: .15;
  }
  30% {
    opacity: 1;
    background: var(--c1);
  }
  60% {
    opacity: .5;
    background: var(--c2);
  }
}

