.ul-ht {
  position: relative;
  width: var(--s);
  height: var(--s);
  display: grid;
  place-items: center;
}

.ul-ht::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 2px solid var(--c1);
  animation: ul-ht-r calc(1.2s / var(--k)) ease-out infinite;
}

.ul-ht b {
  position: relative;
  width: 45%;
  height: 45%;
  background: var(--c1);
  transform: rotate(45deg);
  animation: ul-ht calc(1.2s / var(--k)) ease-in-out infinite;
}

.ul-ht b::before,.ul-ht b::after {
  content: "";
  position: absolute;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: inherit;
}

.ul-ht b::before {
  left: -50%;
}

.ul-ht b::after {
  top: -50%;
}

@keyframes ul-ht {
  0%,40%,100% {
    transform: rotate(45deg) scale(1);
  }
  15% {
    transform: rotate(45deg) scale(1.22);
  }
  28% {
    transform: rotate(45deg) scale(1.08);
  }
}

@keyframes ul-ht-r {
  0% {
    transform: scale(.5);
    opacity: .6;
  }
  100% {
    transform: scale(1.6);
    opacity: 0;
  }
}
`;

export default function LoaderHeart() {
  return (
