.uv-ldn {
  --c1: #ec4899;
  --c2: #3b82f6;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-ldn {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  display: flex;
  gap: .45em;
  height: 5em;
  align-items: center;
}

.uv-ldn .sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.uv-ldn span {
  position: relative;
  width: .55em;
  height: 100%;
}

.uv-ldn i {
  position: absolute;
  left: 0;
  top: 50%;
  width: .55em;
  height: .55em;
  margin-top: -.275em;
  border-radius: 50%;
  animation: uv-ldn calc(1.8s / var(--k)) ease-in-out infinite;
  animation-delay: calc(var(--i) * calc(-0.15s / var(--k)));
}

.uv-ldn .a {
  background: var(--c1);
}

.uv-ldn .b {
  background: var(--c2);
  animation-name: uv-ldn-b;
}

.uv-ldn b {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 1.5px;
  height: 3.6em;
  margin: -1.8em 0 0 -.75px;
  background: linear-gradient(var(--c1),var(--c2));
  opacity: .18;
  animation: uv-ldn-l calc(1.8s / var(--k)) ease-in-out infinite;
  animation-delay: calc(var(--i) * calc(-0.15s / var(--k)));
}

@keyframes uv-ldn {
  0%,100% {
    transform: translateY(-1.8em) scale(.6);
    opacity: .5;
    z-index: 0;
  }
  25% {
    transform: translateY(0) scale(1);
    opacity: 1;
    z-index: 2;
  }
  50% {
    transform: translateY(1.8em) scale(.6);
    opacity: .5;
  }
  75% {
    transform: translateY(0) scale(.4);
    opacity: .3;
    z-index: 0;
  }
}

@keyframes uv-ldn-b {
  0%,100% {
    transform: translateY(1.8em) scale(.6);
    opacity: .5;
  }
  25% {
    transform: translateY(0) scale(.4);
    opacity: .3;
    z-index: 0;
  }
  50% {
    transform: translateY(-1.8em) scale(.6);
    opacity: .5;
  }
  75% {
    transform: translateY(0) scale(1);
    opacity: 1;
    z-index: 2;
  }
}

@keyframes uv-ldn-l {
  0%,50%,100% {
    transform: scaleY(1);
  }
  25%,75% {
    transform: scaleY(0);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uv-ldn,.uv-ldn *,.uv-ldn *::before,.uv-ldn *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

