.uv-lat {
  --c1: #8b5cf6;
  --c2: #22d3ee;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-lat {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  display: inline-flex;
  align-items: center;
  gap: .6em;
  font-size: calc(var(--s) * 1.15);
  font-weight: 650;
}

.uv-lat .st {
  position: relative;
  display: grid;
  width: 1.4em;
  height: 1.4em;
}

.uv-lat svg {
  width: 100%;
  height: 100%;
  fill: url(#uv-lat-g);
  fill: var(--c1);
  animation: uv-lat-p calc(1.6s / var(--k)) ease-in-out infinite;
}

.uv-lat .st i {
  position: absolute;
  width: .32em;
  height: .32em;
  border-radius: 50%;
  background: var(--c2);
  animation: uv-lat-t calc(1.6s / var(--k)) ease-in-out infinite;
}

.uv-lat .st i:nth-of-type(1) {
  right: -.25em;
  top: -.1em;
}

.uv-lat .st i:nth-of-type(2) {
  left: -.2em;
  bottom: -.05em;
  width: .22em;
  height: .22em;
  animation-delay: calc(-0.8s / var(--k));
}

.uv-lat .tx {
  background: linear-gradient(90deg,color-mix(in srgb,var(--fg) 55%,transparent) 0%,color-mix(in srgb,var(--fg) 55%,transparent) 35%,var(--c1) 45%,var(--c2) 55%,color-mix(in srgb,var(--fg) 55%,transparent) 65%,color-mix(in srgb,var(--fg) 55%,transparent) 100%) 0 0/300% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: uv-lat calc(2s / var(--k)) linear infinite;
}

@keyframes uv-lat {
  from {
    background-position: 100% 0;
  }
  to {
    background-position: 0 0;
  }
}

@keyframes uv-lat-p {
  50% {
    transform: scale(.78) rotate(45deg);
  }
}

@keyframes uv-lat-t {
  0%,100% {
    transform: scale(.3);
    opacity: 0;
  }
  50% {
    transform: scale(1);
    opacity: 1;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uv-lat,.uv-lat *,.uv-lat *::before,.uv-lat *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

