  0% {
    opacity: 0;
    transform: translateY(100%);
  }
  5%,22% {
    opacity: 1;
    transform: none;
  }
  27%,100% {
    opacity: 0;
    transform: translateY(-100%);
  }
}

@keyframes uv-lsw-s {
  to {
    transform: rotate(1turn);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uv-lsw .wd span {
    animation: none;
  }
  .uv-lsw .wd span:last-child {
    opacity: 1;
    transform: none;
  }
  .uv-lsw .sp {
    animation-duration: calc(2.4s / var(--k));
  }
}

