}

.uvq10-gau .hub {
  position: absolute;
  left: 50%;
  top: 50%;
  width: .9em;
  height: .9em;
  margin: -.45em;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 35%,#4b5563,#0b0c0e);
  box-shadow: 0 0 0 .08em #6b7280;
}

@keyframes uvq10-gau {
  0% {
    transform: rotate(-120deg);
  }
  38% {
    transform: rotate(117deg);
  }
  44% {
    transform: rotate(110deg);
  }
  50% {
    transform: rotate(115deg);
  }
  82%,100% {
    transform: rotate(-120deg);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq10-gau,.uvq10-gau *,.uvq10-gau *::before,.uvq10-gau *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

