.uvq10-pix {
  --c1: #ff7b39;
  --c2: #2a6f97;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq10-pix {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
}

.uvq10-pix .sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.uvq10-pix .im {
  position: relative;
  width: 10.5em;
  height: 7em;
  border-radius: .6em;
  overflow: hidden;
  background: color-mix(in srgb,var(--fg) 10%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 10%,transparent),0 1em 1.6em -1em rgba(0,0,0,.5);
}

.uvq10-pix svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

.uvq10-pix .px {
  shape-rendering: crispEdges;
}

.uvq10-pix .l0 {
  animation: uvq10-pix-0 calc(4.4s / var(--k)) steps(1) infinite;
}

.uvq10-pix .l1 {
  animation: uvq10-pix-1 calc(4.4s / var(--k)) steps(1) infinite;
}

.uvq10-pix .vc {
  animation: uvq10-pix-2 calc(4.4s / var(--k)) infinite;
}

.uvq10-pix .pg {
  position: absolute;
  left: 0;
  bottom: 0;
  height: .22em;
  width: 100%;
  transform-origin: 0 50%;
  background: #fff;
  mix-blend-mode: difference;
  animation: uvq10-pix-p calc(4.4s / var(--k)) cubic-bezier(.25,.1,.25,1) infinite;
}

.uvq10-pix .p0 {
  fill: color-mix(in oklab,color-mix(in oklab,var(--c1) 20%,var(--c2)) 50%,#fff);
}

.uvq10-pix .p1 {
  fill: color-mix(in oklab,color-mix(in oklab,var(--c1) 40%,var(--c2)) 50%,#fff);
}

.uvq10-pix .p2 {
  fill: color-mix(in oklab,color-mix(in oklab,var(--c1) 57%,var(--c2)) 70%,#fff);
}

.uvq10-pix .p3 {
  fill: color-mix(in oklab,color-mix(in oklab,var(--c1) 50%,var(--c2)) 60%,#fff);
}

.uvq10-pix .p4 {
  fill: color-mix(in oklab,color-mix(in oklab,var(--c1) 50%,var(--c2)) 60%,color-mix(in oklab,#fff 75%,#000));
}

.uvq10-pix .p5 {
  fill: color-mix(in oklab,color-mix(in oklab,var(--c1) 83%,var(--c2)) 60%,#fff);
}

.uvq10-pix .p6 {
  fill: color-mix(in oklab,color-mix(in oklab,var(--c1) 17%,var(--c2)) 60%,#000);
}

.uvq10-pix .p7 {
  fill: color-mix(in oklab,color-mix(in oklab,var(--c1) 60%,var(--c2)) 50%,#000);
}

.uvq10-pix .p8 {
  fill: color-mix(in oklab,color-mix(in oklab,var(--c1) 33%,var(--c2)) 60%,#fff);
}

.uvq10-pix .p9 {
  fill: color-mix(in oklab,var(--c1) 60%,#fff);
}

.uvq10-pix .p10 {
  fill: color-mix(in oklab,color-mix(in oklab,var(--c1) 67%,var(--c2)) 60%,#fff);
}

.uvq10-pix .p11 {
  fill: color-mix(in oklab,color-mix(in oklab,var(--c1) 43%,var(--c2)) 70%,color-mix(in oklab,#fff 67%,#000));
}

.uvq10-pix .p12 {
  fill: color-mix(in oklab,color-mix(in oklab,var(--c1) 17%,var(--c2)) 60%,color-mix(in oklab,#fff 25%,#000));
}

.uvq10-pix .p13 {
  fill: color-mix(in oklab,color-mix(in oklab,var(--c1) 50%,var(--c2)) 60%,color-mix(in oklab,#fff 50%,#000));
}

.uvq10-pix .p14 {
  fill: color-mix(in oklab,color-mix(in oklab,var(--c1) 29%,var(--c2)) 70%,color-mix(in oklab,#fff 33%,#000));
}

.uvq10-pix .p15 {
  fill: color-mix(in oklab,color-mix(in oklab,var(--c1) 40%,var(--c2)) 50%,#000);
}

.uvq10-pix .p16 {
  fill: color-mix(in oklab,color-mix(in oklab,var(--c1) 33%,var(--c2)) 60%,#000);
}

.uvq10-pix .s0 {
  stop-color: color-mix(in oklab,var(--c2) 50%,#fff);
}

.uvq10-pix .s1 {
  stop-color: color-mix(in oklab,color-mix(in oklab,var(--c1) 79%,var(--c2)) 70%,#fff);
}

.uvq10-pix .sun {
  fill: color-mix(in oklab,var(--c1) 60%,#fff);
}

.uvq10-pix .far {
  fill: color-mix(in oklab,color-mix(in oklab,var(--c1) 8%,var(--c2)) 60%,#000);
}

.uvq10-pix .near {
  fill: color-mix(in oklab,color-mix(in oklab,var(--c1) 60%,var(--c2)) 50%,#000);
}

@keyframes uvq10-pix-0 {
  0% {
    opacity: 0;
  }
  8%,100% {
    opacity: 1;
  }
}

@keyframes uvq10-pix-1 {
  0% {
    opacity: 0;
  }
  30%,100% {
    opacity: 1;
  }
}

@keyframes uvq10-pix-2 {
  0%,54% {
    opacity: 0;
    filter: blur(6px);
  }
  56% {
    opacity: 1;
    filter: blur(5px);
  }
  76%,100% {
    opacity: 1;
    filter: blur(0);
  }
}

@keyframes uvq10-pix-p {
  0% {
    transform: scaleX(0);
    opacity: 1;
  }
  8% {
    transform: scaleX(.2);
  }
  30% {
    transform: scaleX(.5);
  }
  56% {
    transform: scaleX(.8);
  }
  76% {
    transform: scaleX(1);
    opacity: 1;
  }
  86%,100% {
    transform: scaleX(1);
    opacity: 0;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq10-pix,.uvq10-pix *,.uvq10-pix *::before,.uvq10-pix *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

