css:
.uvq10-dom {
  --c1: #1d1d22;
  --c2: #f7f3e8;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq10-dom {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 11.4em;
  height: 2.6em;
}

.uvq10-dom .sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.uvq10-dom .fl {
  position: absolute;
  left: -.4em;
  right: -.4em;
  bottom: 0;
  height: 2px;
  border-radius: 2px;
  background: color-mix(in srgb,var(--fg) 25%,transparent);
}

.uvq10-dom .dm {
  position: absolute;
  bottom: 2px;
  left: calc(var(--i) * 1.7em);
  width: .9em;
  height: 1.8em;
  border-radius: .14em;
  transform-origin: 100% 100%;
  background-color: var(--c1);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.14),inset .12em .12em .2em rgba(255,255,255,.12),.08em .12em .25em rgba(0,0,0,.35);
}

.uvq10-dom .dm::after {
  content: "";
  position: absolute;
  left: 18%;
  right: 18%;
  top: 50%;
  height: 1px;
  background: color-mix(in srgb,var(--c2) 60%,transparent);
}

.uvq10-dom .d0 {
  background-image: radial-gradient(circle at 25% 12%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 25% 25%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 25% 38%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 75% 12%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 75% 25%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 75% 38%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 25% 62%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 75% 62%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 50% 75%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 25% 88%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 75% 88%,var(--c2) .075em,transparent .09em);
  animation: uvq10-dom-0 calc(4.2s / var(--k)) infinite;
}

.uvq10-dom .d1 {
  background-image: radial-gradient(circle at 25% 12%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 75% 12%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 25% 38%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 75% 38%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 25% 62%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 50% 75%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 75% 88%,var(--c2) .075em,transparent .09em);
  animation: uvq10-dom-1 calc(4.2s / var(--k)) infinite;
}

.uvq10-dom .d2 {
  background-image: radial-gradient(circle at 25% 12%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 75% 38%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 50% 75%,var(--c2) .075em,transparent .09em);
  animation: uvq10-dom-2 calc(4.2s / var(--k)) infinite;
}

.uvq10-dom .d3 {
  background-image: radial-gradient(circle at 25% 12%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 75% 12%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 50% 25%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 25% 38%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 75% 38%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 25% 62%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 75% 88%,var(--c2) .075em,transparent .09em);
  animation: uvq10-dom-3 calc(4.2s / var(--k)) infinite;
}

.uvq10-dom .d4 {
  background-image: radial-gradient(circle at 25% 12%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 50% 25%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 75% 38%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 25% 62%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 25% 75%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 25% 88%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 75% 62%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 75% 75%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 75% 88%,var(--c2) .075em,transparent .09em);
  animation: uvq10-dom-4 calc(4.2s / var(--k)) infinite;
}

.uvq10-dom .d5 {
  background-image: radial-gradient(circle at 50% 25%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 25% 62%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 75% 62%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 25% 88%,var(--c2) .075em,transparent .09em),radial-gradient(circle at 75% 88%,var(--c2) .075em,transparent .09em);
  animation: uvq10-dom-5 calc(4.2s / var(--k)) infinite;
}

@keyframes uvq10-dom-0 {
  0%,4% {
    transform: rotate(0);
    animation-timing-function: cubic-bezier(.55,0,.85,.4);
  }
  10%,86% {
    transform: rotate(26deg);
    animation-timing-function: cubic-bezier(.2,.6,.3,1);
  }
  92%,100% {
    transform: rotate(0);
  }
}

@keyframes uvq10-dom-1 {
  0%,11% {
    transform: rotate(0);
    animation-timing-function: cubic-bezier(.55,0,.85,.4);
  }
  17%,82% {
    transform: rotate(26deg);
    animation-timing-function: cubic-bezier(.2,.6,.3,1);
  }
  88%,100% {
    transform: rotate(0);
  }
}

@keyframes uvq10-dom-2 {
  0%,18% {
    transform: rotate(0);
    animation-timing-function: cubic-bezier(.55,0,.85,.4);
  }
  24%,78% {
    transform: rotate(26deg);
    animation-timing-function: cubic-bezier(.2,.6,.3,1);
  }
  84%,100% {
    transform: rotate(0);
  }
}

@keyframes uvq10-dom-3 {
  0%,25% {
    transform: rotate(0);
    animation-timing-function: cubic-bezier(.55,0,.85,.4);
  }
  31%,74% {
    transform: rotate(26deg);
    animation-timing-function: cubic-bezier(.2,.6,.3,1);
  }
  80%,100% {
    transform: rotate(0);
  }
}

@keyframes uvq10-dom-4 {
  0%,32% {
    transform: rotate(0);
    animation-timing-function: cubic-bezier(.55,0,.85,.4);
  }
  38%,70% {
    transform: rotate(26deg);
    animation-timing-function: cubic-bezier(.2,.6,.3,1);
  }
  76%,100% {
    transform: rotate(0);
  }
}

@keyframes uvq10-dom-5 {
  0%,39% {
    transform: rotate(0);
    animation-timing-function: cubic-bezier(.55,0,.85,.4);
  }
  45%,66% {
    transform: rotate(90deg);
    animation-timing-function: cubic-bezier(.2,.6,.3,1);
  }
  72%,100% {
    transform: rotate(0);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq10-dom,.uvq10-dom *,.uvq10-dom *::before,.uvq10-dom *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq10-dom .dm {
    animation: none!important;
  }
}

